package org.mockito.internal.matchers;

import org.hamcrest.Description;
import org.mockito.ArgumentMatcher;

import java.io.Serializable;


public class Same extends ArgumentMatcher<Object> implements Serializable {

    private static final long serialVersionUID = -1226959355938572597L;
    private final Object wanted;

    public Same(Object wanted) {
        this.wanted = wanted;
    }

    public boolean matches(Object candidate) {
        Object expected = this.wanted;
        return expected == candidate;
    }

    public void describeTo(Description description) {
        description.appendText("same(");
        appendDelimiter(description);
        description.appendText(this.wanted.toString());
        appendDelimiter(description);
        description.appendText(")");
    }

    private void appendDelimiter(Description description) {
        Object target = this.wanted;

        if (target instanceof String) {
            description.appendText("\"");
            return;
        }

        if (target instanceof Character) {
            description.appendText("'");
        }
    }
}
